function generateStaffId(PDO $pdo): string {
    do { $id = 'OKF-' . strtoupper(substr(bin2hex(random_bytes(3)), 0, 6)); $st = $pdo->prepare("SELECT COUNT(*) FROM staff WHERE staff_code = ?"); $st->execute([$id]); } while ((int)$st->fetchColumn() > 0);
    return $id;
}
$nextStaffId = generateStaffId($pdo);
$flash = null;

if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='_create') {
    $d = $_POST;
    $name=trim($d['full_name']??''); $email=trim($d['email']??''); $phone=trim($d['phone']??'');
    $staffCode=strtoupper(trim($d['staff_code']??'')); $position=trim($d['position']??'');
    $dept=trim($d['department']??''); $role=$d['role']??'Staff';
    $errs=[];
    if(strlen($name)<3)$errs[]='Full name required';
    if(!$staffCode)$errs[]='Staff ID required';
    if(!$position)$errs[]='Position required';
    if(empty($errs)){
        try{
            $rst=$pdo->prepare("SELECT id FROM roles WHERE LOWER(name)=LOWER(?)");$rst->execute([$role]);$rr=$rst->fetch();$roleId=$rr?(int)$rr['id']:4;
            $staffData = [
                'user_id'=>null,'staff_code'=>$staffCode,'full_name'=>$name,
                'passport_photo'=>$d['passport_photo']??null,'date_of_birth'=>$d['date_of_birth']?:null,
                'gender'=>$d['gender']?:null,'nin'=>trim($d['nin']??''),'state_of_origin'=>trim($d['state_of_origin']??''),
                'lga'=>trim($d['lga']??''),'nationality'=>trim($d['nationality']??'Nigerian'),
                'marital_status'=>$d['marital_status']?:null,'religion'=>trim($d['religion']??''),
                'blood_group'=>trim($d['blood_group']??''),'genotype'=>trim($d['genotype']??''),
                'disability'=>trim($d['disability']??''),'highest_education'=>trim($d['highest_education']??''),
                'institution'=>trim($d['institution']??''),'graduation_year'=>$d['graduation_year']?:null,
                'field_of_study'=>trim($d['field_of_study']??''),'certifications'=>trim($d['certifications']??''),
                'prev_company'=>trim($d['prev_company']??''),'prev_position'=>trim($d['prev_position']??''),
                'prev_duration'=>trim($d['prev_duration']??''),'prev_responsibilities'=>trim($d['prev_responsibilities']??''),
                'guarantor_name'=>trim($d['guarantor_name']??''),'guarantor_phone'=>trim($d['guarantor_phone']??''),
                'guarantor_address'=>trim($d['guarantor_address']??''),'guarantor_relationship'=>trim($d['guarantor_relationship']??''),
                'guarantor_occupation'=>trim($d['guarantor_occupation']??''),'bank_name'=>trim($d['bank_name']??''),
                'bank_account_no'=>trim($d['bank_account_no']??''),'bank_account_name'=>trim($d['bank_account_name']??''),
                'tax_id'=>trim($d['tax_id']??''),'pension_pin'=>trim($d['pension_pin']??''),
                'nhis_number'=>trim($d['nhis_number']??''),'emergency_contact_name'=>trim($d['emergency_contact_name']??''),
                'emergency_contact_phone'=>trim($d['emergency_contact_phone']??''),
                'emergency_contact_relation'=>trim($d['emergency_contact_relation']??''),
                'address'=>trim($d['address']??''),'next_of_kin'=>trim($d['next_of_kin']??''),
                'next_of_kin_phone'=>trim($d['next_of_kin_phone']??''),'salary'=>floatval($d['salary']??0),
                'employment_type'=>$d['employment_type']??'Full-Time','position'=>$position,'department'=>$dept,
                'phone'=>$phone?:null,'email'=>$email,'hire_date'=>$d['hire_date']??date('Y-m-d'),
                'status'=>'Active','notes'=>trim($d['notes']??'')
            ];
            $tableCols = $pdo->query("SHOW COLUMNS FROM staff")->fetchAll(PDO::FETCH_COLUMN);
            $matchedCols=[];$matchedVals=[];
            foreach ($staffData as $col=>$val) { if (in_array($col,$tableCols)) { $matchedCols[]="`$col`"; $matchedVals[]=$val; } }
            $placeholders = implode(',', array_fill(0, count($matchedCols), '?'));
            $pdo->prepare("INSERT INTO staff (".implode(',',$matchedCols).") VALUES ($placeholders)")->execute($matchedVals);
            try{$pdo->prepare("INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details)VALUES(?,?,?,?,?)")->execute([$auth['id'],'CREATE_STAFF','staff',(int)$pdo->lastInsertId(),"Created: $name ($staffCode)"]);}catch(Exception $ignore){}
            $flash=['type'=>'success','msg'=>"Staff '$name' ($staffCode) created!"];
        }catch(Exception $e){$errs[]='DB error: '.$e->getMessage();}
    }
    if(!empty($errs))$flash=['type'=>'error','msg'=>implode('. ',$errs)];
}

