                'tax_id'=>trim($d['tax_id']??''),'pension_pin'=>trim($d['pension_pin']??''),
                'nhis_number'=>trim($d['nhis_number']??''),'emergency_contact_name'=>trim($d['emergency_contact_name']??''),
                'emergency_contact_phone'=>trim($d['emergency_contact_phone']??''),
                'emergency_contact_relation'=>trim($d['emergency_contact_relation']??''),
                'address'=>trim($d['address']??''),'next_of_kin'=>trim($d['next_of_kin']??''),
                'next_of_kin_phone'=>trim($d['next_of_kin_phone']??''),'salary'=>floatval($d['salary']??0),
                'employment_type'=>$d['employment_type']??'Full-Time','position'=>trim($d['position']??''),
                'department'=>trim($d['department']??''),'phone'=>trim($d['phone']??''),
                'status'=>$d['status']??'Active','notes'=>trim($d['notes']??'')
            ];
            $sets=[];$vals=[];
            foreach($upd as $col=>$val){ if(in_array($col,$tableCols)){ $sets[]="`$col`=?"; $vals[]=$val; } }
            $vals[]=$id;
            $pdo->prepare("UPDATE staff SET ".implode(',',$sets)." WHERE id=?")->execute($vals);
            try{$pdo->prepare("INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details)VALUES(?,?,?,?,?)")->execute([$auth['id'],'UPDATE_STAFF','staff',$id,"Updated: ".trim($d['full_name'])]);}catch(Exception $ignore){}
            $flash=['type'=>'success','msg'=>'Staff updated!'];
        }catch(Exception $e){$flash=['type'=>'error','msg'=>'Update failed: '.$e->getMessage()];}
    } else { $flash=['type'=>'error','msg'=>'Name required.']; }
    header('Location: staff_directory.php'); exit;
}

if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='_delete') {
    $id=(int)($_POST['staff_id']??0);
    if($id>0){
        try{
            $pdo->prepare("DELETE FROM staff WHERE id=?")->execute([$id]);
            try{$pdo->prepare("INSERT INTO activity_logs(user_id,action,entity_type,entity_id,details)VALUES(?,?,?,?,?)")->execute([$auth['id'],'DELETE_STAFF','staff',$id,"Deleted ID $id"]);}catch(Exception $ignore){}
            $flash=['type'=>'success','msg'=>'Staff deleted.'];
        }catch(Exception $e){$flash=['type'=>'error','msg'=>'Delete failed: '.$e->getMessage()];}
    }
    header('Location: staff_directory.php'); exit;
}

$search=trim($_GET['search']??'');$filterDept=$_GET['department']??'';$filterStatus=$_GET['status']??'';
$where=[];$params=[];
if($search!==''){$where[]="(s.full_name LIKE ? OR s.staff_code LIKE ? OR s.phone LIKE ?)";$params[]="%$search%";$params[]="%$search%";$params[]="%$search%";}
if($filterDept!==''){$where[]="s.department = ?";$params[]=$filterDept;}
if($filterStatus!==''){$where[]="s.status = ?";$params[]=$filterStatus;}
$wc=$where?'WHERE '.implode(' AND ',$where):'';
$staffList=[];
try{
    $st=$pdo->prepare("SELECT s.*, r.name AS role_name FROM staff s LEFT JOIN users u ON u.id=s.user_id LEFT JOIN roles r ON r.id=u.role_id $wc ORDER BY s.created_at DESC LIMIT 100");
    $st->execute($params);$staffList=$st->fetchAll();
}catch(Exception $ignore){}
$totalStaff=count($staffList);$activeStaff=0;foreach($staffList as $s)if(($s['status']??'Active')==='Active')$activeStaff++;

