.toasts{position:fixed;top:76px;right:18px;z-index:120;display:flex;flex-direction:column;gap:10px}.toast{display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--line);border-left:4px solid var(--green);border-radius:12px;padding:12px 16px;font-size:13px;font-weight:700;box-shadow:var(--shadow);animation:slidein .3s;max-width:380px}.toast.error{border-left-color:var(--red)}.toast.out{opacity:0;transform:translateX(20px);transition:.4s}@keyframes slidein{from{transform:translateX(30px);opacity:0}to{transform:none;opacity:1}}
#printSheet{display:none}
@media(max-width:1020px){.page-header{flex-direction:column;align-items:flex-start}}@media(max-width:768px){.fgrid{grid-template-columns:1fr}.filter-bar{flex-direction:column}.ff{min-width:100%}.topbar .badge{display:none}.brand strong{font-size:12px}.actions-cell{flex-direction:column;gap:4px}.actions-cell .btn-sm{width:100%;justify-content:center}.m-body{padding:18px}.photo-upload{flex-direction:column;text-align:center}.m-header{padding:18px}}@media(max-width:480px){.header-stats{flex-direction:column;gap:6px}.header-btns{width:100%}.header-btns .btn{flex:1}}
