function toast(msg,type){var t=document.createElement('div');t.className='toast '+(type==='error'?'error':'');t.innerHTML='<span>'+(type==='error'?'⚠️':'✅')+'</span>'+msg;$('toastWrap').appendChild(t);setTimeout(function(){t.classList.add('out')},3500);setTimeout(function(){t.remove()},4000);}
function openModal(id){$(id).classList.add('open')}
function closeModal(id){$(id).classList.remove('open')}
document.querySelectorAll('.modal-overlay').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m)m.classList.remove('open')})});
document.addEventListener('keydown',function(e){if(e.key==='Escape')document.querySelectorAll('.modal-overlay.open').forEach(function(m){m.classList.remove('open')})});
$('btnCreateOpen').addEventListener('click',function(){$('createForm').reset();$('create_photo_preview').innerHTML='<svg class="icon-svg" viewBox="0 0 24 24"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';$('create_photo_data').value='';openModal('createModal')});
function previewPhoto(input,previewId,dataId){var file=input.files[0];if(!file)return;if(file.size>512000){toast('Photo must be under 500KB','error');input.value='';return;}var reader=new FileReader();reader.onload=function(ev){$(previewId).innerHTML='<img src="'+ev.target.result+'">';$(dataId).value=ev.target.result;};reader.readAsDataURL(file);}

