function qrSvg(str,px){var n=21;var h=2166136261;for(var i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619);}var seed=Math.abs(h)||1;var rnd=function(){seed=(Math.imul(seed,1103515245)+12345)&0x7fffffff;return seed/0x7fffffff;};var cells='';var finder=function(ox,oy){for(var y=0;y<7;y++)for(var x=0;x<7;x++){var edge=x===0||x===6||y===0||y===6;var core=x>=2&&x<=4&&y>=2&&y<=4;if(edge||core)cells+='<rect x="'+(ox+x)+'" y="'+(oy+y)+'" width="1" height="1"/>';}};finder(0,0);finder(n-7,0);finder(0,n-7);for(var y=0;y<n;y++)for(var x=0;x<n;x++){var inF=(x<8&&y<8)||(x>=n-8&&y<8)||(x<8&&y>=n-8);if(!inF&&rnd()>0.52)cells+='<rect x="'+x+'" y="'+y+'" width="1" height="1"/>';}return '<svg viewBox="0 0 '+n+' '+n+'" fill="#141f19" shape-rendering="crispEdges" style="width:'+px+';height:'+px+'">'+cells+'</svg>';}
function barcodeSvg(str){var hsh=0;for(var i=0;i<str.length;i++)hsh=(hsh*31+str.charCodeAt(i))>>>0;var seed=hsh||1;var rnd=function(){seed=(Math.imul(seed,1103515245)+12345)&0x7fffffff;return seed/0x7fffffff;};var bars='',bx=0;var total=160;while(bx<total){var w=rnd()>0.5?2.2:1.2;var gap=rnd()>0.5?1.4:2.4;if(rnd()>0.25)bars+='<rect x="'+bx.toFixed(1)+'" y="0" width="'+w+'" height="100"/>';bx+=w+gap;}return '<svg viewBox="0 0 '+total+' 100" preserveAspectRatio="none" fill="#1a231d">'+bars+'</svg>';}

