function printHTML(bodyHTML){var old=document.getElementById('printFrame');if(old)old.remove();var iframe=document.createElement('iframe');iframe.id='printFrame';iframe.style.position='fixed';iframe.style.right='0';iframe.style.bottom='0';iframe.style.width='0';iframe.style.height='0';iframe.style.border='0';document.body.appendChild(iframe);var doc=iframe.contentWindow.document;doc.open();doc.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Print</title><link href="https://cdn.jsdelivr.net/fontsource/fonts/sora@latest/latin-800-normal.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/fontsource/fonts/manrope@latest/latin-400-normal.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/fontsource/fonts/jetbrains-mono@latest/latin-500-normal.css" rel="stylesheet"><style>'+IDC_CSS+'</style></head><body>'+bodyHTML+'</body></html>');doc.close();iframe.contentWindow.focus();setTimeout(function(){iframe.contentWindow.print();setTimeout(function(){iframe.remove();},1000);},500);}

function findStaff(sid){for(var i=0;i<staffData.length;i++){if(staffData[i].id===sid)return staffData[i];}return null;}

/* PROFILE PRINT */
document.querySelectorAll('.btn-print-profile').forEach(function(b){b.addEventListener('click',function(){
  var sid=parseInt(b.getAttribute('data-sid'));var s=findStaff(sid);if(!s){toast('Staff not found','error');return;}
  var row=function(l,val){return '<div class="psp-row"><span>'+l+'</span><b>'+v(val)+'</b></div>';};
  var docId='SP-'+s.staff_code+'-'+new Date().toISOString().slice(0,10).replace(/-/g,'');
  var genDate=new Date().toLocaleString('en-NG',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'});
  var statusCls='st-'+(s.status||'Active').toLowerCase();
  var photoHtml=s.passport_photo?'<img class="psp-photo" src="'+s.passport_photo+'" alt="">':'<div class="psp-photo-ph">PASSPORT<br>PHOTO</div>';
  var html='<div class="psp"><div class="psp-head"><img class="psp-logo" src="'+logoAbs+'" alt="Logo"><div class="psp-co"><h1>'+cn+'</h1><p>'+ca+'</p><p>Staff Management &amp; HR</p><div class="tag">POVERTY ERADICATION &middot; REDUCE INEQUALITY &middot; LEAVE NO ONE BEHIND</div></div><div class="psp-doc"><h2>STAFF PROFILE</h2><p>Ref: <span class="ref">'+docId+'</span></p><p>'+genDate+'</p></div></div><div class="psp-summary">'+photoHtml+'<div class="psp-id"><h3>'+v(s.full_name)+'</h3><div class="pos">'+v(s.position)+' &mdash; '+v(s.department)+'</div><div class="psp-idmeta"><span class="psp-chip id">'+s.staff_code+'</span><span class="psp-chip role">'+(s.role||'STAFF').toUpperCase()+'</span><span class="psp-chip '+statusCls+'">'+(s.status||'Active').toUpperCase()+'</span></div><div class="psp-barcode">'+barcodeSvg(s.staff_code)+'</div></div><div class="psp-qrwrap"><div class="psp-qrbox">'+qrSvg(s.staff_code+s.full_name,'100%')+'</div><span>VERIFY</span></div></div><div class="psp-cols"><div class="psp-sec"><h4>Personal</h4><div class="psp-sec-body">'+row('Name',s.full_name)+row('DOB',s.date_of_birth)+row('Gender',s.gender)+row('NIN',s.nin)+row('Nationality',s.nationality)+row('State',s.state_of_origin)+row('LGA',s.lga)+row('Marital',s.marital_status)+row('Religion',s.religion)+row('Blood/Geno',(s.blood_group?s.blood_group+(s.genotype?' / '+s.genotype:''):null))+row('Disability',s.disability)+row('Address',s.address)+'</div></div><div class="psp-sec"><h4>Employment</h4><div class="psp-sec-body">'+row('Staff ID',s.staff_code)+row('Role',s.role||'Staff')+row('Position',s.position)+row('Department',s.department)+row('Type',s.employment_type)+row('Salary',s.salary?'₦'+Number(s.salary).toLocaleString():null)+row('Hire Date',s.hire_date)+row('Status',s.status)+row('Phone',s.phone)+row('Email',s.email)+'</div></div><div class="psp-sec"><h4>Education</h4><div class="psp-sec-body">'+row('Education',s.highest_education)+row('Institution',s.institution)+row('Field',s.field_of_study)+row('Grad Year',s.graduation_year)+row('Certs',s.certifications)+'</div></div><div class="psp-sec"><h4>Experience</h4><div class="psp-sec-body">'+row('Company',s.prev_company)+row('Position',s.prev_position)+row('Duration',s.prev_duration)+row('Duties',s.prev_responsibilities)+'</div></div><div class="psp-sec"><h4>Guarantor</h4><div class="psp-sec-body">'+row('Name',s.guarantor_name)+row('Relation',s.guarantor_relationship)+row('Occupation',s.guarantor_occupation)+row('Phone',s.guarantor_phone)+row('Address',s.guarantor_address)+'</div></div><div class="psp-sec"><h4>Banking</h4><div class="psp-sec-body">'+row('Bank',s.bank_name)+row('Account',s.bank_account_no)+row('Acc Name',s.bank_account_name)+row('TIN',s.tax_id)+row('Pension',s.pension_pin)+row('NHIS',s.nhis_number)+'</div></div><div class="psp-sec wide"><h4>Emergency &amp; NOK</h4><div class="psp-sec-body" style="display:grid;grid-template-columns:1fr 1fr;gap:0 14pt">'+row('Emergency',s.emergency_contact_name)+row('EC Phone',s.emergency_contact_phone)+row('EC Relation',s.emergency_contact_relation)+row('NOK',s.next_of_kin)+row('NOK Phone',s.next_of_kin_phone)+'</div></div></div>'+(s.notes?'<div class="psp-sec" style="margin-top:7pt"><h4>Notes</h4><div class="psp-note">'+v(s.notes)+'</div></div>':'')+'<div class="psp-decl"><b>DECLARATION:</b> I, <b>'+v(s.full_name)+'</b>, certify all information is true.</div><div class="psp-sigs"><div class="psp-sig"><div class="psp-sigline"></div><span>Staff</span><small>Name &amp; Date</small></div><div class="psp-sig"><div class="psp-sigline"></div><span>HR Manager</span><small>Signature &amp; Date</small></div><div class="psp-sig"><div class="psp-sigline"></div><span>MD</span><small>Signature &amp; Date</small></div><div class="psp-sig"><div class="psp-stamp">COMPANY<br>STAMP</div><span style="margin-top:3pt">Seal</span></div></div><div class="psp-foot"><span>'+cn+' &mdash; CONFIDENTIAL</span><span>'+docId+'</span></div></div>';
  printHTML(html);
})});

