  var opt=function(l){return '<span class="pbf-opt"><span class="pbf-box"></span>'+l+'</span>';};
  var formNo='REG-'+new Date().toISOString().slice(0,10).replace(/-/g,'');
  var html='<div class="pbf"><div class="pbf-head"><img class="pbf-logo" src="'+logoAbs+'" alt=""><div class="pbf-co"><h1>'+cn+'</h1><p>'+ca+'</p><p>Staff Management &amp; HR</p><div class="tag">POVERTY ERADICATION &middot; REDUCE INEQUALITY &middot; LEAVE NO ONE BEHIND</div></div><div class="pbf-doc"><h2>REGISTRATION FORM</h2><p>'+formNo+'</p></div></div><div class="pbf-photo-row"><div class="pbf-photobox"><b>PASSPORT PHOTO</b>Affix here<br>(35x40mm)</div><div class="pbf-instr"><b>INSTRUCTIONS</b>1. BLOCK LETTERS.<br>2. (*) = compulsory.<br>3. Attach photo &amp; valid ID.<br>4. False info = dismissal.<br>5. Submit to HR.</div></div><div class="pbf-sec"><h3>A &mdash; Personal</h3><div class="pbf-sec-body"><div class="pbf-grid">'+f('1. Full Name *',true)+f('2. DOB')+f('3. Place of Birth')+'<div class="pbf-f"><label>4. Gender *</label><div class="pbf-opts">'+opt('Male')+opt('Female')+'</div></div>'+f('5. NIN')+f('6. Nationality')+f('7. State')+f('8. LGA')+'<div class="pbf-f"><label>9. Marital</label><div class="pbf-opts">'+opt('Single')+opt('Married')+opt('Divorced')+opt('Widowed')+'</div></div>'+f('10. Religion')+f('11. Blood')+f('12. Genotype')+f('13. Address',true,true)+f('14. Phone')+f('15. Email')+'</div></div></div><div class="pbf-sec"><h3>B &mdash; Employment</h3><div class="pbf-sec-body"><div class="pbf-grid"><div class="pbf-f pbf-wide"><label>16. Role *</label><div class="pbf-opts">'+opt('Admin')+opt('Secretary')+opt('Staff')+opt('Workers')+opt('Cleaner')+opt('GM')+'</div></div>'+f('17. Department')+f('18. Position *')+'<div class="pbf-f"><label>19. Type</label><div class="pbf-opts">'+opt('Full-Time')+opt('Part-Time')+opt('Contract')+opt('Intern')+'</div></div>'+f('20. Salary')+f('21. Resumption')+'</div></div></div><div class="pbf-sec"><h3>C &mdash; Education</h3><div class="pbf-sec-body"><div class="pbf-grid">'+f('22. Qualification')+f('23. Institution')+f('24. Field')+f('25. Grad Year')+f('26. Certifications',true,true)+'</div></div></div><div class="pbf-sec"><h3>D &mdash; Experience</h3><div class="pbf-sec-body"><div class="pbf-grid">'+f('27. Employer')+f('28. Position')+f('29. Duration')+f('30. Reason')+f('31. Duties',true,true)+'</div></div></div><div class="pbf-sec"><h3>E &mdash; Guarantor</h3><div class="pbf-sec-body"><div class="pbf-grid">'+f('32. Name *')+f('33. Relationship')+f('34. Occupation')+f('35. Phone')+f('36. Address',true,true)+'</div></div></div><div class="pbf-sec"><h3>F &mdash; Banking</h3><div class="pbf-sec-body"><div class="pbf-grid">'+f('37. Bank')+f('38. Account No')+f('39. Account Name')+f('40. TIN')+f('41. Pension')+f('42. NHIS')+'</div></div></div><div class="pbf-sec"><h3>G &mdash; Emergency &amp; NOK</h3><div class="pbf-sec-body"><div class="pbf-grid">'+f('43. EC Name *')+f('44. EC Phone')+f('45. EC Relation')+f('46. NOK')+f('47. NOK Phone')+f('48. NOK Address')+'</div></div></div><div class="pbf-sec"><h3>H &mdash; Declaration</h3><div class="pbf-sec-body"><p style="font-size:6.5pt;color:#5a655c;line-height:1.6;margin-bottom:8pt">I declare all information is true. False info may result in dismissal.</p><div class="pbf-sigs" style="margin-top:0;grid-template-columns:1fr 1fr 62pt"><div class="pbf-sig"><div class="pbf-sigline"></div><span>Applicant</span><small>Name &amp; Date</small></div><div class="pbf-sig"><div class="pbf-sigline"></div><span>Guarantor</span><small>Name &amp; Date</small></div><div class="pbf-sig"><div class="pbf-stampbox">OFFICIAL<br>STAMP</div></div></div></div></div><div class="pbf-office"><h4>Office Use Only</h4><div class="pbf-office-grid"><div class="pbf-f"><label>Received By</label><div class="pbf-line tall"></div></div><div class="pbf-f"><label>Approved By</label><div class="pbf-line tall"></div></div><div class="pbf-stampbox">SEAL</div></div></div><div class="pbf-foot"><span>'+cn+' &mdash; '+formNo+'</span><span>Confidential</span></div></div>';
