/* BUILD ID CARD WITH ALL STYLES INLINE */
function buildIdCard(s,forPrint){
  var rs=getRoleStyle(s.role);
  var c1=rs[0],c2=rs[1],roleLabel=rs[2];
  var issue=s.hire_date?new Date(s.hire_date).toLocaleDateString('en-NG',{month:'short',year:'numeric'}):new Date().toLocaleDateString('en-NG',{month:'short',year:'numeric'});
  var exp=new Date(new Date().getFullYear()+3,new Date().getMonth(),new Date().getDate()).toLocaleDateString('en-NG',{month:'short',year:'numeric'});
  var logoSrc=forPrint?logoAbs:'logo.ico';
  var bandBg='background:linear-gradient(120deg,'+c1+','+c2+')';
  var photoHtml=s.passport_photo?'<img style="width:60px;height:72px;border-radius:6px;object-fit:cover;border:2px solid '+c1+';flex:none" src="'+s.passport_photo+'" alt="">':'<div style="width:60px;height:72px;border-radius:6px;border:2px solid '+c1+';background:#f0f2ee;display:flex;align-items:center;justify-content:center;font-size:6pt;color:#8a968c;text-align:center;flex:none">NO<br>PHOTO</div>';

  var front='<div style="width:324px;height:204px;border-radius:12px;overflow:hidden;background:#fff;border:1px solid #ccc;flex-shrink:0;font-family:Manrope,Arial,sans-serif">'
    +'<div style="'+bandBg+';color:#fff;display:flex;align-items:center;gap:8px;padding:8px 12px">'
      +'<img style="width:32px;height:32px;border-radius:6px;background:#fff;padding:2px;object-fit:contain;flex:none" src="'+logoSrc+'" alt="">'
      +'<div style="flex:1"><b style="font-family:Sora,sans-serif;font-size:9px;font-weight:800;display:block;line-height:1.15">'+cn+'</b><span style="font-size:6px;opacity:.85;font-weight:600;display:block">STAFF IDENTIFICATION CARD</span></div>'
      +'<span style="font-size:6px;font-weight:800;letter-spacing:1px;background:rgba(255,255,255,.22);border:1pt solid rgba(255,255,255,.4);padding:3px 7px;border-radius:99px;white-space:nowrap">'+roleLabel+'</span>'
    +'</div>'
    +'<div style="flex:1;display:flex;gap:10px;padding:8px 12px;position:relative">'
      +'<div style="position:absolute;top:6px;right:10px;width:26px;height:26px;border-radius:50%;background:conic-gradient(from 180deg,rgba(255,215,130,.85),rgba(255,255,255,.5),rgba(190,225,205,.8),rgba(255,215,130,.85));opacity:.75"></div>'
      +'<div>'+photoHtml+'</div>'
      +'<div style="flex:1;display:flex;flex-direction:column;gap:2px;justify-content:center">'
        +'<div style="font-family:Sora,sans-serif;font-size:12px;font-weight:800;line-height:1.15">'+s.full_name+'</div>'
        +'<div style="font-size:7.5px;font-weight:800;color:'+c1+';text-transform:uppercase;letter-spacing:.5px">'+(s.position||'Staff')+'</div>'
        +'<div style="display:flex;flex-direction:column;gap:1.5px;margin-top:2px">'
          +'<div style="display:flex;font-size:6.5pt;line-height:1.3"><span style="color:#7a857c;font-weight:700;width:42px;flex:none;text-transform:uppercase;font-size:5.5pt;padding-top:1pt">ID</span><b style="font-family:JetBrains Mono,monospace;letter-spacing:.8pt;font-size:7.5pt;font-weight:700">'+s.staff_code+'</b></div>'
          +'<div style="display:flex;font-size:6.5pt;line-height:1.3"><span style="color:#7a857c;font-weight:700;width:42px;flex:none;text-transform:uppercase;font-size:5.5pt;padding-top:1pt">DEPT</span><b style="font-weight:700;font-size:7pt">'+(s.department||'General')+'</b></div>'
          +'<div style="display:flex;font-size:6.5pt;line-height:1.3"><span style="color:#7a857c;font-weight:700;width:42px;flex:none;text-transform:uppercase;font-size:5.5pt;padding-top:1pt">PHONE</span><b style="font-weight:700;font-size:7pt">'+(s.phone||'—')+'</b></div>'
          +'<div style="display:flex;font-size:6.5pt;line-height:1.3"><span style="color:#7a857c;font-weight:700;width:42px;flex:none;text-transform:uppercase;font-size:5.5pt;padding-top:1pt">NIN</span><b style="font-weight:700;font-size:7pt">'+(s.nin||'N/A')+'</b></div>'
          +'<div style="display:flex;font-size:6.5pt;line-height:1.3"><span style="color:#7a857c;font-weight:700;width:42px;flex:none;text-transform:uppercase;font-size:5.5pt;padding-top:1pt">VALID</span><b style="font-weight:700;font-size:7pt">'+issue+' — '+exp+'</b></div>'
        +'</div>'
      +'</div>'
    +'</div>'
    +'<div style="'+bandBg+';color:#fff;padding:4px 12px;display:flex;justify-content:space-between;align-items:center;font-size:5.5pt;font-weight:700;letter-spacing:.8px"><span>OKOYA FOOD CO. LTD</span><b style="font-family:JetBrains Mono,monospace;font-size:6.5pt;letter-spacing:1.5px">'+s.staff_code+'</b></div>'
  +'</div>';

  var back='<div style="width:324px;height:204px;border-radius:12px;overflow:hidden;background:#fff;border:1px solid #ccc;flex-shrink:0;font-family:Manrope,Arial,sans-serif">'
    +'<div style="'+bandBg+';color:#fff;padding:5px 12px;font-family:Sora,sans-serif;font-size:7.5px;font-weight:800;letter-spacing:.5pt;display:flex;justify-content:space-between;align-items:center"><span>'+cn+'</span><span>'+s.staff_code+'</span></div>'
    +'<div style="flex:1;display:flex;gap:10px;padding:8px 12px">'
      +'<div style="flex:none;display:flex;flex-direction:column;align-items:center;gap:2px"><div style="width:72px;height:72px;border:1.5pt solid #141f19;border-radius:5px;padding:3px;background:#fff">'+qrSvg(s.staff_code+s.full_name,'100%')+'</div><span style="font-family:JetBrains Mono,monospace;font-size:6pt;font-weight:700;letter-spacing:1.5px">'+s.staff_code+'</span></div>'
      +'<div style="flex:1;display:flex;flex-direction:column;gap:4px;font-size:6pt;color:#4a554c;line-height:1.4">'
        +'<div><h5 style="font-size:6pt;font-weight:800;text-transform:uppercase;letter-spacing:.8pt;margin-bottom:1pt">HOLDER</h5><p style="font-size:5.5pt;line-height:1.45;color:#5a655c"><b>'+s.full_name+'</b><br>'+(s.position||'Staff')+' — '+(s.department||'General')+'</p></div>'
        +'<div><h5 style="font-size:6pt;font-weight:800;text-transform:uppercase;letter-spacing:.8pt;margin-bottom:1pt">EMERGENCY</h5><p style="font-size:5.5pt;line-height:1.45;color:#5a655c">'+(s.emergency_contact_name||'N/A')+'<br>'+(s.emergency_contact_phone||'—')+'</p></div>'
        +'<div><h5 style="font-size:6pt;font-weight:800;text-transform:uppercase;letter-spacing:.8pt;margin-bottom:1pt">TERMS</h5><p style="font-size:5.5pt;line-height:1.45;color:#5a655c">Property of '+cn+'. Return if found.</p></div>'
        +'<div style="margin-top:auto;border-top:1.5pt solid #141f19;padding-top:2pt;display:flex;justify-content:space-between;font-size:5.5pt;font-weight:800;text-transform:uppercase;letter-spacing:.6pt;color:#4a554c"><span>Holder Sig</span><span>Authorised</span></div>'
      +'</div>'
    +'</div>'
    +'<div style="background:#f0f2ee;padding:4px 12px;font-size:5pt;color:#7a857c;text-align:center;font-weight:600">'+ca+' &middot; '+issue+'</div>'
  +'</div>';

  return {front:front,back:back};
}

/* ID CARD BUTTON */
document.querySelectorAll('.btn-print-id').forEach(function(b){b.addEventListener('click',function(){
  var sid=parseInt(b.getAttribute('data-sid'));
  var s=findStaff(sid);
  if(!s){toast('Staff not found','error');return;}
  var c=buildIdCard(s,false);
  $('idModalBody').innerHTML='<div style="display:flex;flex-direction:column;gap:22px;align-items:center">'+
    '<div style="font-size:10px;font-weight:800;letter-spacing:1.5px;color:var(--ink2);text-transform:uppercase">FRONT</div>'+c.front+
    '<div style="font-size:10px;font-weight:800;letter-spacing:1.5px;color:var(--ink2);text-transform:uppercase;margin-top:10px">BACK</div>'+c.back+
    '</div>'+
    '<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:20px">'+
    '<button class="btn btn-ghost" onclick="downloadIdCard()"><svg class="icon-svg" viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>PNG</button>'+
    '<button class="btn btn-primary" onclick="printIdCard()"><svg class="icon-svg" viewBox="0 0 24 24"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg>Print</button>'+
    '<button class="btn btn-ghost" onclick="closeModal(\'idModal\')">Close</button></div>';
  window._currentIdStaff=s;
  openModal('idModal');
})});

function printIdCard(){
  var s=window._currentIdStaff;if(!s)return;
  var c=buildIdCard(s,true);
  printHTML('<div style="display:flex;gap:10mm;align-items:flex-start;page-break-inside:avoid"><div style="display:flex;flex-direction:column;align-items:center;gap:3mm"><div style="font-size:7pt;font-weight:800;letter-spacing:2px;color:#999;text-transform:uppercase">FRONT</div>'+c.front+'</div><div style="display:flex;flex-direction:column;align-items:center;gap:3mm"><div style="font-size:7pt;font-weight:800;letter-spacing:2px;color:#999;text-transform:uppercase">BACK</div>'+c.back+'</div></div><div style="margin-top:5mm;text-align:center;font-size:6.5pt;color:#aaa;letter-spacing:1pt">CUT ALONG EDGES &mdash; CR80 (85.6mm x 54mm)</div>');
}

function downloadIdCard(){
  var s=window._currentIdStaff;if(!s)return;
  var rs=getRoleStyle(s.role),W=680,H=428,SC=2;
  var cv=document.createElement('canvas');cv.width=W*SC;cv.height=H*SC;
  var x=cv.getContext('2d');x.scale(SC,SC);
  var rr=function(a,b,w,h,r){x.beginPath();x.moveTo(a+r,b);x.arcTo(a+w,b,a+w,b+h,r);x.arcTo(a+w,b+h,a,b+h,r);x.arcTo(a,b+h,a,b,r);x.arcTo(a,b,a+w,b,r);x.closePath();};
  rr(0,0,W,H,14);x.fillStyle='#fff';x.fill();x.save();rr(0,0,W,H,14);x.clip();
  var g=x.createLinearGradient(0,0,W,0);g.addColorStop(0,rs[0]);g.addColorStop(1,rs[1]);
  x.fillStyle=g;x.fillRect(0,0,W,84);
  x.fillStyle='#fff';x.beginPath();x.arc(34,42,20,0,7);x.fill();
  x.fillStyle=rs[0];x.font='800 22px Sora,sans-serif';x.fillText('O',27,50);
  x.fillStyle='#fff';x.font='800 19px Sora,sans-serif';x.fillText(cn,66,40);
  x.font='600 10px Manrope,sans-serif';x.globalAlpha=.85;x.fillText('STAFF ID CARD',66,58);x.globalAlpha=1;
  x.font='800 11px Manrope,sans-serif';
  var roleW=x.measureText(rs[2]).width+22;
  rr(W-roleW-16,28,roleW,26,13);x.fillStyle='rgba(255,255,255,.22)';x.fill();
  x.fillStyle='#fff';x.fillText(rs[2],W-roleW-16+11,45);
  var drawBody=function(){
    x.strokeStyle=rs[0];x.lineWidth=4;rr(26,106,120,144,6);x.stroke();
    if(s.passport_photo){var img=new Image();img.onload=function(){x.save();rr(28,108,120,144,6);x.clip();x.drawImage(img,28,108,120,144);x.restore();finish();};img.src=s.passport_photo;}
    else{rr(28,108,120,144,6);x.fillStyle='#f0f2ee';x.fill();x.fillStyle='#8a968c';x.font='600 12px Manrope,sans-serif';x.textAlign='center';x.fillText('NO PHOTO',88,185);finish();}
    var finish=function(){
      x.fillStyle='#141f19';x.font='800 26px Sora,sans-serif';x.fillText(s.full_name,170,140);
      x.fillStyle=rs[0];x.font='800 13px Manrope,sans-serif';x.fillText((s.position||'Staff').toUpperCase(),170,162);
      var row=function(lbl,val,y,mono){x.fillStyle='#7a857c';x.font='800 9px Manrope,sans-serif';x.fillText(lbl.toUpperCase(),170,y);x.fillStyle='#182420';x.font=(mono?'700 13px JetBrains Mono,monospace':'700 13px Manrope,sans-serif');x.fillText(val||'—',240,y);};
      row('ID',s.staff_code,192,true);row('DEPT',s.department||'General',214);row('PHONE',s.phone,236);row('NIN',s.nin||'N/A',258);
      x.fillStyle=g;x.fillRect(0,H-46,W,46);
      x.fillStyle='#fff';x.font='700 11px Manrope,sans-serif';x.fillText('OKOYA FOOD CO. LTD',26,H-18);
      x.font='700 13px JetBrains Mono,monospace';x.fillText(s.staff_code,W-140,H-18);
      var a=document.createElement('a');a.download=s.staff_code+'_id_card.png';a.href=cv.toDataURL('image/png');a.click();
      toast('ID downloaded','success');
    };
  };
  drawBody();x.restore();
}

