next_of_kin_phone||'';$('edit_notes').value=s.notes||'';$('edit_photo_data').value=s.passport_photo||'';$('edit_photo_preview').innerHTML=s.passport_photo?'<img src="'+s.passport_photo+'">':'<svg class="icon-svg" viewBox="0 0 24 24"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
